            C

    // importing the required libraries
#include <stdio.h>
#include <string.h>
#include <openssl/md5.h>

int main() {
    // making a message
    unsigned char digest[MD5_DIGEST_LENGTH];
    char inputstring[] = "This is a message sent by a computer user.";

    // encoding the message using the library function
    MD5((unsigned char*)&inputstring, strlen(inputstring), digest);

    // printing the hash function
    printf("Hash of the input string:\n");
    for(int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", digest[i]);
    }
    printf("\n");
    return 0;
}


            Java

    // importing the required libraries
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class Main {
    public static void main(String[] args) {
        // making a message
        String inputstring = "This is a message sent by a computer user.";
        try {
            // encoding the message using the library function
            MessageDigest md = MessageDigest.getInstance("MD5");
            md.update(inputstring.getBytes());
            byte[] digest = md.digest();

            // printing the hash function
            System.out.println("Hash of the input string:");
            StringBuilder hexString = new StringBuilder();
            for (byte b : digest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            System.out.println(hexString.toString());
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }
}


